  ('P01', 'poi-media/foto/p01_1.jpg', 'Gerbang barat dari arah Jl. Banten', 1),
  ('P01', 'poi-media/foto/p01_2.jpg', 'Papan peta zona taman di dekat gerbang', 2),
  ('P18', 'poi-media/foto/p18_1.jpg', 'Loket tiket di bawah tenda', 1),
  ('P18', 'poi-media/foto/p18_2.jpg', 'Papan harga tiket masuk', 2),
  ('P07', 'poi-media/foto/p07_1.jpg', 'Skuter dan sepeda listrik Papa Skuter', 1),
  ('P07', 'poi-media/foto/p07_2.jpg', 'Area sewa di dekat Taman Asia Afrika', 2),
