insert into public.wellness_trail (id, name, subtitle, description, level, distance_m, est_minutes, best_times, color, path, sort_order) values ('T01', 'Rute Santai Kelilingi Danau', 'Jalan santai dengan peregangan dan latihan napas', 'Rute jalan kaki santai mengelilingi danau melewati musala, zona teduh, dan Taman Asia Afrika. Setiap checkpoint memutar panduan audio berisi info spot dan ajakan peregangan atau latihan napas.', 'Santai', 670, 15, array['pagi', 'sore']::text[], '#3f9e8e', '[[-6.915268,107.641752],[-6.915232,107.641795],[-6.915206,107.641834],[-6.915188,107.641871],[-6.915177,107.641906],[-6.91517,107.641941],[-6.915168,107.641977],[-6.915167,107.642016],[-6.915168,107.642058],[-6.915168,107.642106],[-6.915166,107.64216],[-6.91516,107.642223],[-6.915152,107.642295],[-6.915143,107.642374],[-6.915135,107.642457],[-6.915129,107.642541],[-6.915127,107.642625],[-6.915131,107.642705],[-6.915143,107.64278],[-6.915164,107.642845],[-6.915196,107.642899],[-6.915242,107.642944],[-6.9153,107.642983],[-6.91537,107.643016],[-6.915447,107.643044],[-6.915529,107.643067],[-6.915614,107.643086],[-6.9157,107.643099],[-6.915782,107.643108],[-6.91586,107.643112],[-6.91593,107.643112],[-6.915996,107.643108],[-6.916062,107.643099],[-6.916127,107.643085],[-6.916191,107.643066],[-6.916253,107.643043],[-6.916312,107.643016],[-6.916367,107.642983],[-6.916417,107.642947],[-6.916461,107.642906],[-6.916499,107.64286],[-6.916528,107.642807],[-6.916547,107.642744],[-6.916558,107.642674],[-6.916564,107.642598],[-6.916567,107.642519],[-6.916569,107.642439],[-6.916573,107.642362],[-6.91658,107.642288],[-6.916595,107.64222],[-6.916617,107.642161],[-6.916655,107.64211],[-6.916709,107.642066],[-6.916773,107.642026],[-6.916842,107.64199],[-6.916911,107.641957],[-6.916974,107.641924],[-6.917025,107.641891],[-6.91706,107.641856],[-6.917072,107.641818],[-6.917055,107.641775],[-6.917007,107.641724],[-6.916931,107.641663],[-6.916832,107.641597],[-6.916716,107.641527],[-6.916588,107.641459],[-6.916455,107.641395],[-6.916321,107.64134],[-6.916193,107.641295],[-6.916077,107.641265],[-6.915977,107.641254],[-6.915888,107.641263],[-6.915802,107.64129],[-6.915718,107.641331],[-6.915637,107.641384],[-6.915561,107.641445],[-6.91549,107.641511],[-6.915424,107.641577],[-6.915365,107.641642],[-6.915312,107.641702],[-6.915268,107.641752]]'::jsonb, 1);
insert into public.trail_checkpoint (trail_id, seq, name, poi_id, location, radius_m, exercise, coaching) values
  ('T01', 1, 'Titik Start Jogging Track', 'P06', extensions.st_setsrid(extensions.st_makepoint(107.6417524, -6.9152676), 4326)::extensions.geography, 25, 'Pemanasan 1 menit', 'Checkpoint satu, titik start. Yuk pemanasan! Putar pergelangan kaki kanan dan kiri masing-masing lima kali, lalu ayunkan kedua lengan ke depan dan ke belakang. Setelah itu, jalan santai ke timur menuju musala.'),
  ('T01', 2, 'Musala & Toilet', 'P10', extensions.st_setsrid(extensions.st_makepoint(107.6421597, -6.9151658), 4326)::extensions.geography, 20, 'Cek hidrasi', 'Checkpoint dua, sisi utara taman. Di sini ada musala dan toilet. Kalau haus, minum beberapa teguk air. Jaga postur: bahu rileks, pandangan ke depan. Lanjut ke timur menuju Zona Teduh.'),
  ('T01', 3, 'Zona Teduh', 'P11', extensions.st_setsrid(extensions.st_makepoint(107.643112, -6.91593), 4326)::extensions.geography, 20, 'Peregangan ringan 1 menit', 'Checkpoint tiga, Zona Teduh. Saatnya peregangan ringan satu menit. Tarik lengan kanan menyilang ke depan dada, tahan sepuluh hitungan, lalu ganti lengan kiri. Kemudian tarik napas empat hitungan dan hembuskan enam hitungan. Ulangi tiga kali.'),
  ('T01', 4, 'Taman Asia Afrika', 'P05', extensions.st_setsrid(extensions.st_makepoint(107.6421607, -6.9166173), 4326)::extensions.geography, 25, 'Latihan napas 4-6', 'Checkpoint empat, Taman Asia Afrika. Pandang danau dan air mancur di utara. Tarik napas dalam empat hitungan, hembuskan enam hitungan. Rasakan langkahmu jadi lebih ringan. Lanjut ke barat lalu ke utara, kembali ke titik start.'),
  ('T01', 5, 'Finish: Titik Start', 'P06', extensions.st_setsrid(extensions.st_makepoint(107.6417524, -6.9152676), 4326)::extensions.geography, 25, 'Pendinginan', 'Hore, kamu menyelesaikan Rute Santai Kelilingi Danau! Yuk pendinginan: tarik tumit ke arah bokong untuk meregangkan paha depan, tahan lima belas hitungan untuk tiap kaki. Jangan lupa minum air, ya.');
insert into public.wellness_trail (id, name, subtitle, description, level, distance_m, est_minutes, best_times, color, path, sort_order) values ('T02', 'Jogging Lingkar Kiara Artha', 'Satu putaran jogging di lingkar Jl. Kiara Artha', 'Rute jogging mengikuti lingkar Jl. Kiara Artha yang mengelilingi taman. Panduan audio di tiap sisi taman membantu menjaga ritme langkah dan napas. Ulangi untuk menambah jarak.', 'Sedang', 760, 10, array['pagi', 'sore']::text[], '#ee7b5b', '[[-6.915208,107.641662],[-6.915149,107.641736],[-6.915098,107.641814],[-6.915055,107.641896],[-6.915019,107.64198],[-6.914993,107.642066],[-6.914974,107.642154],[-6.914965,107.642242],[-6.914964,107.642331],[-6.914972,107.642419],[-6.914988,107.642506],[-6.915014,107.642591],[-6.915047,107.642673],[-6.915089,107.642753],[-6.915139,107.642828],[-6.915196,107.642899],[-6.91526,107.642966],[-6.91533,107.643027],[-6.915407,107.643082],[-6.915489,107.64313],[-6.915576,107.643173],[-6.915667,107.643208],[-6.915761,107.643236],[-6.915858,107.643256],[-6.915957,107.643269],[-6.916058,107.643274],[-6.916159,107.643272],[-6.916259,107.643262],[-6.916358,107.643244],[-6.916456,107.643218],[-6.916551,107.643186],[-6.916643,107.643146],[-6.91673,107.643099],[-6.916813,107.643047],[-6.916891,107.642988],[-6.916963,107.642923],[-6.917028,107.642854],[-6.917087,107.64278],[-6.917138,107.642702],[-6.917181,107.64262],[-6.917217,107.642536],[-6.917243,107.64245],[-6.917262,107.642362],[-6.917271,107.642274],[-6.917272,107.642185],[-6.917264,107.642097],[-6.917248,107.64201],[-6.917222,107.641925],[-6.917189,107.641843],[-6.917147,107.641763],[-6.917097,107.641688],[-6.91704,107.641617],[-6.916976,107.64155],[-6.916906,107.641489],[-6.916829,107.641434],[-6.916747,107.641386],[-6.91666,107.641343],[-6.916569,107.641308],[-6.916475,107.64128],[-6.916378,107.64126],[-6.916279,107.641247],[-6.916178,107.641242],[-6.916077,107.641244],[-6.915977,107.641254],[-6.915878,107.641272],[-6.91578,107.641298],[-6.915685,107.64133],[-6.915593,107.64137],[-6.915506,107.641417],[-6.915423,107.641469],[-6.915345,107.641528],[-6.915273,107.641593],[-6.915208,107.641662]]'::jsonb, 2);
insert into public.trail_checkpoint (trail_id, seq, name, poi_id, location, radius_m, exercise, coaching) values
  ('T02', 1, 'Start: Sisi Barat Laut', null, extensions.st_setsrid(extensions.st_makepoint(107.641662, -6.915208), 4326)::extensions.geography, 25, 'Pemanasan dinamis', 'Selamat datang di Jogging Lingkar Kiara Artha! Pemanasan dinamis dulu: angkat lutut bergantian selama tiga puluh detik. Lalu mulai jogging pelan searah jarum jam.'),
  ('T02', 2, 'Sisi Timur Laut', null, extensions.st_setsrid(extensions.st_makepoint(107.64313, -6.915489), 4326)::extensions.geography, 25, 'Atur ritme napas', 'Checkpoint dua, sisi timur laut. Atur ritme napas: tarik napas dua langkah, hembuskan dua langkah. Kamu seharusnya masih bisa ngobrol dengan nyaman.'),
  ('T02', 3, 'Sisi Tenggara', null, extensions.st_setsrid(extensions.st_makepoint(107.642854, -6.917028), 4326)::extensions.geography, 25, 'Postur lari', 'Checkpoint tiga, sisi tenggara. Cek postur: badan tegak sedikit condong ke depan, lengan menekuk sembilan puluh derajat, dan mendarat dengan tengah telapak kaki.'),
  ('T02', 4, 'Sisi Barat Daya', null, extensions.st_setsrid(extensions.st_makepoint(107.641434, -6.916829), 4326)::extensions.geography, 25, 'Jaga kecepatan', 'Checkpoint empat, sisi barat daya. Sedikit lagi! Pertahankan kecepatan yang nyaman. Area kuliner ada di sebelah kananmu kalau mau istirahat setelah ini.'),
  ('T02', 5, 'Finish: Sisi Barat Laut', null, extensions.st_setsrid(extensions.st_makepoint(107.641662, -6.915208), 4326)::extensions.geography, 25, 'Pendinginan', 'Satu putaran selesai, keren! Jalan pelan dua menit untuk pendinginan, lalu regangkan betis dengan bertumpu pada dinding atau pohon.');
