insert into public.quiz_question (poi_id, trail_id, seq, question, options, answer_index, explanation) values
  ('P01', null, 1, 'Kapan Kiara Artha Park diresmikan?', array['24 April 2019', '17 Agustus 2019', '1 Januari 2020', '17 Agustus 2015']::text[], 1, 'Taman ini diresmikan 17 Agustus 2019, bertepatan dengan HUT ke-74 Republik Indonesia.'),
  ('P01', null, 2, 'Kiara Artha Park berada di antara dua flyover. Flyover apa saja?', array['Pelangi dan Pasupati', 'Antapani dan Kiaracondong', 'Pasupati dan Cimindi', 'Cimindi dan Antapani']::text[], 1, 'Taman ini terletak di antara flyover Antapani dan flyover Kiaracondong, Kelurahan Kebonwaru.'),
  ('P18', null, 1, 'Berapa harga tiket masuk per orang menurut papan di loket?', array['Rp5.000', 'Rp10.000', 'Gratis', 'Rp25.000']::text[], 1, 'Papan di loket mencantumkan Rp10.000 per orang untuk usia 6 tahun ke atas.'),
  ('P18', null, 2, 'Tiket Rp10.000 berlaku untuk usia berapa?', array['Semua usia', '12 tahun ke atas', '17 tahun ke atas', '6 tahun ke atas']::text[], 3, 'Papan harga menyebut tiket berlaku untuk usia 6 tahun ke atas.'),
  ('P07', null, 1, 'Papa Skuter berada di sebelah spot apa?', array['Gerbang Utara', 'Musala & Toilet', 'Taman Asia Afrika', 'Lapangan padel']::text[], 2, 'Papa Skuter ada di area dalam, sebelah Solaria dan Taman Asia Afrika.'),
  ('P07', null, 2, 'Saat naik skuter di lingkar taman, siapa yang harus diutamakan?', array['Mobil', 'Pejalan kaki', 'Tidak ada', 'Skuter yang lebih cepat']::text[], 1, 'Jalur lingkar dipakai bersama; pejalan kaki selalu diutamakan.'),
  ('P05', null, 1, 'Konferensi Asia Afrika 1955 digelar di gedung apa di Bandung?', array['Gedung Kembar', 'Gedung Merdeka', 'Gedung Sate', 'Gedung Pakuan']::text[], 1, 'KAA digelar di Gedung Merdeka, Bandung, 18–24 April 1955.'),
  ('P05', null, 2, 'Berapa negara yang hadir di Konferensi Asia Afrika 1955?', array['29 negara', '55 negara', '100 negara', '10 negara']::text[], 0, 'Konferensi Asia Afrika 1955 dihadiri 29 negara.'),
  ('P08', null, 1, 'Paket Kiara Pelangi Food Court Rp35.000 disebut sudah termasuk apa?', array['Akses menonton air mancur menari', 'Sewa sepeda satu jam', 'Tiket masuk taman', 'Parkir gratis']::text[], 0, 'Paketnya disebut sudah termasuk akses menonton air mancur menari (Orami, 2024).'),
  ('P08', null, 2, 'Kafe dekat area ini yang punya rating 4,8 dengan lebih dari seribu ulasan di Google Maps?', array['Kopi Kiara', 'Ludo Sports Kitchen and Coffee', 'Kopi Taman Kota', 'Padel Co.']::text[], 1, 'Ludo Sports Kitchen and Coffee punya lebih dari seribu ulasan dengan rating 4,8.'),
  ('P03', null, 1, 'Jam berapa pertunjukan air mancur menari biasanya dimulai?', array['21.00', '16.00', '18.30', '12.00']::text[], 2, 'Pertunjukan umumnya mulai pukul 18.30 sampai 20.30, dengan pertunjukan berbeda tiap jam (Orami, 2024).'),
  ('P03', null, 2, 'Apa nama patung jabat tangan di tepi utara danau?', array['Patung Merdeka', 'Monumen Persahabatan', 'Friendship Shake Hand', 'Tugu Asia Afrika']::text[], 2, 'Patung Friendship Shake Hand menggambarkan jabat tangan persahabatan, sejalan dengan semangat Asia Afrika.'),
  ('P15', null, 1, 'Tenan mana yang ada di Food Court 2?', array['Padel Co.', 'Kiara Pelangi', 'Ludo Sports Kitchen', 'Steak Ranjang']::text[], 3, 'Food Court 2 berisi Steak Ranjang, Siloka, Pang Waffle, dan RD Coffee & Eatery.'),
  ('P15', null, 2, 'Kira-kira berapa jarak Food Court 2 ke danau?', array['±140 m', '±1 km', '±600 m', '±10 m']::text[], 0, 'Danau dan air mancur sekitar 140 meter ke arah barat dari sini.'),
  ('P14', null, 1, 'Gerbang Timur menghadap jalan apa?', array['Jl. Pasirkoja', 'Jl. H. Ibrahim Adjie', 'Jl. Banten', 'Jl. Jakarta']::text[], 1, 'Gerbang Timur ada di sisi Jl. H. Ibrahim Adjie, arah Kiaracondong.'),
  ('P14', null, 2, 'Spot apa yang tepat berada di sebelah selatan Gerbang Timur?', array['Food Court 2', 'Area parkir', 'Taman Asia Afrika', 'Papa Skuter']::text[], 0, 'Food Court 2 dengan deretan kafe dan resto ada tepat di sebelah selatan gerbang.'),
  ('P11', null, 1, 'Pola napas apa yang Kia ajak latih di Zona Teduh?', array['Napas cepat 20 kali', 'Tarik 4 hitungan, hembuskan 6', 'Tarik 10, tahan 10', 'Tahan napas 1 menit']::text[], 1, 'Menghembuskan napas lebih panjang (6) daripada menarik (4) membantu menenangkan detak jantung.'),
  ('P11', null, 2, 'Mengapa udara di bawah kanopi pohon terasa lebih sejuk?', array['Kanopi menaungi dari terik matahari', 'Karena tanahnya basah', 'Ada pendingin udara', 'Karena dekat parkiran']::text[], 0, 'Kanopi pohon menaungi area di bawahnya sehingga terasa lebih sejuk dibanding area terbuka.'),
  ('P09', null, 1, 'Di negara mana olahraga padel lahir?', array['Inggris', 'Brasil', 'Spanyol', 'Meksiko']::text[], 3, 'Padel lahir di Acapulco, Meksiko, pada 1969.'),
  ('P09', null, 2, 'Apa yang membedakan padel dari tenis?', array['Bola boleh memantul ke dinding', 'Dimainkan sendirian', 'Dimainkan tanpa raket', 'Lapangan tanpa net']::text[], 0, 'Dalam padel, bola boleh memantul ke dinding kaca sebelum dipukul kembali.'),
  ('P10', null, 1, 'Fasilitas apa yang ada di P10?', array['Sewa skuter', 'Lapangan padel', 'Air mancur menari', 'Musala dan toilet']::text[], 3, 'P10 adalah fasilitas musala dan toilet di sisi utara taman.'),
  ('P10', null, 2, 'Musala P10 berdekatan dengan titik apa?', array['Start jogging track', 'Air mancur menari', 'Gerbang Barat', 'Lapangan padel']::text[], 0, 'Musala P10 berada dekat titik start jogging track di sisi utara taman.'),
  ('P06', null, 1, 'Kira-kira berapa panjang satu putaran jalur lingkar taman?', array['±2 km', '±5 km', '±750 m', '±200 m']::text[], 2, 'Jalur lingkar Jl. Kiara Artha sekitar 750 meter per putaran.'),
  ('P06', null, 2, 'Acara lari apa yang pernah digelar di Kiara Artha Park?', array['Pocari Run 2025', 'Jakarta Marathon', 'Tour de Bandung', 'Borobudur Marathon']::text[], 0, 'Kiara Artha Park pernah menjadi tuan rumah acara lari Pocari Run 2025.'),
  ('P13', null, 1, 'Gerbang Utara menghadap jalan apa?', array['Jl. Asia Afrika', 'Jl. Jakarta', 'Jl. Banten', 'Jl. Ibrahim Adjie']::text[], 1, 'Gerbang Utara ada di sisi Jl. Jakarta, terhubung ke taman lewat Jl. Kiara Artha Utara.'),
  ('P13', null, 2, 'Dari Gerbang Utara, ke arah mana lingkar taman?', array['Menyeberang Jl. Jakarta', 'Lurus ke selatan, ±100 m', 'Ke utara, ±1 km', 'Ke barat, ±500 m']::text[], 1, 'Ikuti Jl. Kiara Artha Utara lurus ke selatan sekitar 100 meter.'),
  ('P02', null, 1, 'Berapa tiket masuk per orang menurut detikJabar (2024)?', array['Rp10.000', 'Rp5.000', 'Gratis', 'Rp25.000']::text[], 0, 'Tiket tercatat Rp10.000 per orang, hari kerja maupun akhir pekan. Cek lagi di loket karena harga bisa berubah.'),
  ('P02', null, 2, 'Dari gerbang parkir, ke arah mana Pintu Utama?', array['Utara, sekitar 300 m', 'Selatan, sekitar 90 m', 'Timur, sekitar 500 m', 'Di seberang Jl. Banten']::text[], 1, 'Pintu Utama ada sekitar 90 meter ke arah selatan dari gerbang parkir.'),
  ('P17', null, 1, 'Rest Area 78 berada di jalan apa?', array['Jl. Jakarta', 'Jl. Asia Afrika', 'Jl. Banten', 'Jl. Ibrahim Adjie']::text[], 2, 'Rest Area 78 ada di Jl. Banten No. 78, sisi barat laut taman.'),
  ('P17', null, 2, 'Spot mana yang dekat dengan Rest Area 78?', array['Area parkir', 'Gerbang Timur', 'Food Court 2', 'Zona Teduh']::text[], 0, 'Rest Area 78 berada dekat area parkir di sisi barat laut taman.'),
  ('P16', null, 1, 'Masjid Al-Maleeq berada di sisi mana kawasan Kiara Artha?', array['Timur, dekat Jl. Ibrahim Adjie', 'Barat, dekat Jl. Banten', 'Selatan, di Kiara Pelangi', 'Di tengah danau']::text[], 1, 'Masjid Al-Maleeq ada di sisi barat, di pojok deretan toko dekat Jl. Banten.'),
  ('P16', null, 2, 'Selain masjid ini, di mana lagi bisa salat di taman?', array['Lapangan padel', 'Musala di sisi utara taman', 'Food Court 2', 'Papa Skuter']::text[], 1, 'Ada musala di sisi utara taman, dekat titik start jogging track.'),
  (null, 'T01', 1, 'Pola napas di Rute Santai: tarik berapa hitungan, hembuskan berapa?', array['Tarik 10, hembuskan 10', 'Tarik 6, hembuskan 4', 'Tarik 2, hembuskan 2', 'Tarik 4, hembuskan 6']::text[], 3, 'Hembusan yang lebih panjang (6) dari tarikan (4) membantu tubuh lebih rileks.'),
  (null, 'T01', 2, 'Setelah selesai berjalan, sebaiknya kamu…', array['Langsung lari sprint', 'Pendinginan dan minum air', 'Tidak perlu apa-apa', 'Duduk tanpa bergerak lama']::text[], 1, 'Pendinginan meregangkan otot, dan minum air mengganti cairan yang keluar.'),
  (null, 'T02', 1, 'Saat jogging dengan ritme nyaman, kamu seharusnya…', array['Menahan napas', 'Berhenti tiap 10 meter', 'Masih bisa ngobrol dengan nyaman', 'Terengah-engah tak bisa bicara']::text[], 2, 'Kalau masih bisa ngobrol, intensitas jogging-mu pas.'),
  (null, 'T02', 2, 'Posisi lengan yang dianjurkan saat berlari?', array['Lurus kaku ke bawah', 'Dimasukkan ke saku', 'Menekuk sekitar 90 derajat', 'Diangkat di atas kepala']::text[], 2, 'Lengan menekuk 90 derajat membantu ayunan yang efisien.');
insert into public.mission (poi_id, type, title, prompt, done_label, seconds, cues) values
  ('P01', 'photo', 'Foto pertama di Jurnal', 'Foto gerbang barat dari tempatmu berdiri. Ini jadi halaman pertama Jurnal Kunjunganmu!', null, null, '[]'::jsonb),
  ('P18', 'photo', 'Foto di papan Kiara Artha', 'Ambil foto berlatar papan nama Kiara Artha Park di dekat loket.', null, null, '[]'::jsonb),
  ('P07', 'confirm', 'Pilih skuter favorit', 'Lihat deretan skuter di Papa Skuter. Warna apa yang paling banyak? Perhatikan juga papan tarifnya.', 'Sudah kulihat!', null, '[]'::jsonb),
  ('P05', 'photo', 'Foto ikonik Asia Afrika', 'Menghadaplah ke utara dan ambil foto berlatar danau dan air mancur.', null, null, '[]'::jsonb),
  ('P08', 'photo', 'Foto menu favorit', 'Foto makanan atau minuman yang paling menggoda di area kuliner.', null, null, '[]'::jsonb),
  ('P03', 'confirm', 'Cari patung jabat tangan', 'Lihat ke tepi utara danau dan temukan patung Friendship Shake Hand, dua tangan yang berjabat.', 'Ketemu!', null, '[]'::jsonb),
  ('P15', 'photo', 'Foto menu Food Court 2', 'Foto menu atau tenan favoritmu di Food Court 2.', null, null, '[]'::jsonb),
  ('P14', 'confirm', 'Cari papan nama', 'Temukan papan nama atau tulisan Kiara Artha Park di sekitar gerbang timur.', 'Ketemu!', null, '[]'::jsonb),
  ('P11', 'timer', 'Napas 4-6 selama 60 detik', 'Tarik napas 4 hitungan, hembuskan 6 hitungan. Ikuti aba-aba Kia.', null, 60, '[{"at":0,"text":"Tarik napas."},{"at":4,"text":"Hembuskan perlahan."},{"at":10,"text":"Tarik napas."},{"at":14,"text":"Hembuskan perlahan."},{"at":20,"text":"Tarik napas."},{"at":24,"text":"Hembuskan perlahan."},{"at":30,"text":"Tarik napas."},{"at":34,"text":"Hembuskan perlahan."},{"at":40,"text":"Tarik napas."},{"at":44,"text":"Hembuskan perlahan."},{"at":50,"text":"Tarik napas."},{"at":54,"text":"Hembuskan perlahan."}]'::jsonb),
  ('P09', 'confirm', 'Tonton satu reli', 'Tonton pemain padel sampai satu reli selesai. Perhatikan bola yang memantul ke dinding kaca!', 'Sudah kutonton!', null, '[]'::jsonb),
  ('P10', 'confirm', 'Jaga kebersihan', 'Simpan alas kaki di rak dan buang satu sampah yang kamu lihat ke tempatnya.', 'Sudah!', null, '[]'::jsonb),
  ('P06', 'timer', 'Pemanasan 60 detik', 'Ikuti aba-aba Kia sampai waktunya habis. Gerakkan badan pelan-pelan saja.', null, 60, '[{"at":0,"text":"Putar pergelangan kaki kanan."},{"at":15,"text":"Ganti, putar pergelangan kaki kiri."},{"at":30,"text":"Ayunkan kedua lengan ke depan dan ke belakang."},{"at":45,"text":"Sekarang jalan di tempat."}]'::jsonb),
  ('P13', 'confirm', 'Hitung langkahmu', 'Hitung langkahmu dari gerbang sampai lingkar taman. Lebih atau kurang dari 150 langkah?', 'Sudah kuhitung!', null, '[]'::jsonb),
  ('P02', 'confirm', 'Ingat tempat parkirmu', 'Catat blok atau patokan tempat kendaraanmu diparkir supaya mudah ditemukan saat pulang.', 'Sudah kucatat!', null, '[]'::jsonb),
  ('P17', 'photo', 'Foto menu Rest Area 78', 'Foto menu atau tenan favoritmu di Rest Area 78.', null, null, '[]'::jsonb),
  ('P16', 'confirm', 'Rapikan alas kaki', 'Simpan alas kakimu dengan rapi di tempat yang disediakan, lalu bantu rapikan satu pasang lainnya.', 'Sudah rapi!', null, '[]'::jsonb);
insert into public.kia_faq (id, patterns, answer, poi_id, sort_order) values
  ('tiket', array['tiket', 'harga masuk', 'bayar masuk', 'htm', 'biaya masuk']::text[], 'Tiket masuk Rp10.000 per orang untuk usia 6 tahun ke atas, sesuai papan di loket tiket dekat papan nama Kiara Artha Park.', 'P18', 1),
  ('alamat', array['alamat', 'lokasi taman', 'letak taman', 'taman ini di mana']::text[], 'Kiara Artha Park ada di Jl. Banten, Kebonwaru, Kecamatan Batununggal, Kota Bandung, di antara flyover Antapani dan flyover Kiaracondong.', 'P01', 2),
  ('kontak', array['kontak', 'telepon', 'nomor hp', 'nomor telepon', 'instagram', 'ig', 'pengelola']::text[], 'Info resmi taman: Instagram @kiaraarthapark dan telepon 0822-1583-8889.', null, 3),
  ('angkutan', array['angkot', 'bus', 'transportasi', 'naik apa', 'trans metro', 'kendaraan umum', 'halte']::text[], 'Bus Trans Metro Bandung Koridor 5 berhenti di halte Kiara Artha. Halte Gerbang Utara Kiara Artha Park juga ada di Jl. Jakarta, dekat Gerbang Utara.', 'P13', 4),
  ('sewa', array['sewa sepeda', 'sewa skuter', 'skuter', 'scooter', 'otoped', 'harga sepeda', 'tarif sepeda', 'tarif skuter', 'papa skuter', 'rental']::text[], 'Skuter dan sepeda listrik bisa disewa di Papa Skuter, area dalam sebelah Solaria dan Taman Asia Afrika. Tarif sewa di dalam taman tercatat sekitar Rp30.000 di hari kerja dan Rp40.000 di akhir pekan (detikJabar, 2024); cek lagi di kasir, ya.', 'P07', 5),
  ('paket', array['paket', 'food court', 'makan malam', 'paket makan']::text[], 'Paket Kiara Pelangi Food Court Rp35.000 disebut sudah termasuk akses menonton air mancur menari (Orami, 2024). Konfirmasi lagi di lokasi, ya.', 'P08', 6),
  ('padel', array['booking padel', 'sewa lapangan', 'reservasi', 'pesan lapangan', 'main padel']::text[], 'Lapangan padel dipesan langsung ke pengelola Padel Co. SETARA belum menyediakan reservasi.', 'P09', 7),
  ('kia', array['kamu siapa', 'siapa kamu', 'kia siapa', 'siapa kia', 'kenalan']::text[], 'Aku Kia, tunas pohon kiara! Aku menemanimu menjelajah, membacakan cerita spot, dan memberi kuis serta misi. Makin banyak bintang yang kamu kumpulkan, makin tinggi aku tumbuh.', null, 8),
  ('kiara', array['pohon kiara', 'asal nama', 'arti kiara', 'nama kiara']::text[], 'Kiara adalah pohon sejenis beringin (Ficus). Nama Kiaracondong konon berasal dari pohon kiara yang tumbuh condong.', null, 9),
  ('privasi', array['privasi', 'data saya', 'lokasi saya dikirim', 'aman nggak']::text[], 'Lokasimu hanya diproses di ponsel dan tidak pernah dikirim ke server. Yang terkirim tanpa identitas hanya rating, laporan, hasil kuis, dan pertanyaan yang belum bisa kujawab.', null, 10);
